void Solver::bump_var(int var, double coeff) {
    const double THRESH = 1e100;
    const double SCALE  = 1e-100;

    // increase activity of the variable
    double inc = var_inc * coeff;
    activity[var] += inc;

    // if this variable's activity exceeds the threshold, down‑scale only this entry
    // and the global increment to avoid a full O(vars) pass.
    if (activity[var] > THRESH) {
        activity[var] *= SCALE;
        var_inc *= SCALE;
    }

    // keep the VSIDS heap up‑to‑date
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}
